import zlib from 'node:zlib';
import { encodeRgbaPng } from './generate-private-chest-xray-overlays.mjs';

/** Fixed-layout 3-D NIfTI-1, generated by prepare-spine-mri.mjs. */
export function parsePrivateNifti(bytes, datatype) {
  const b = zlib.gunzipSync(bytes, { maxOutputLength: 256 * 1024 * 1024 });
  if (b.length < 352 || b.readInt32LE(0) !== 348 || b.toString('latin1', 344, 347) !== 'n+1')
    throw Error('REVIEW_UNEXPECTED_NIFTI_HEADER');
  const dimCount = b.readInt16LE(40);
  const dims = [b.readInt16LE(42), b.readInt16LE(44), b.readInt16LE(46)];
  const dtype = b.readInt16LE(70), bitpix = b.readInt16LE(72);
  const offset = b.readFloatLE(108);
  const sform = b.readInt16LE(254);
  if (dimCount !== 3 || dims.some(v => v < 2 || v > 1024) ||
      dims.reduce((a, x) => a * x, 1) > 20000000 ||
      dtype !== datatype || bitpix !== (datatype === 4 ? 16 : 8) ||
      offset !== 352 || sform !== 1 ||
      b.length !== 352 + dims.reduce((a, x) => a * x, 1) * (bitpix / 8)) {
    throw Error('REVIEW_UNSUPPORTED_NIFTI_GRID');
  }
  const affine = Array.from({ length: 12 }, (_, i) => b.readFloatLE(280 + i * 4));
  if (affine.some(x => !Number.isFinite(x))) throw Error('REVIEW_INVALID_NIFTI_AFFINE');
  return { data: b, dims, datatype, offset, affine };
}

/** Source labels are previewed at index-space slices, not a radiological diagnostic orientation. */
export function renderPrivateSpineSlices(mriGzip, labelGzip, labelTable) {
  const mri = parsePrivateNifti(mriGzip, 4), labels = parsePrivateNifti(labelGzip, 2);
  if (mri.dims.join() !== labels.dims.join() ||
      mri.affine.some((v, i) => Math.abs(v - labels.affine[i]) > 1e-4)) {
    throw Error('REVIEW_SPINE_IMAGE_LABEL_REGISTRATION_MISMATCH');
  }
  if (!labelTable || labelTable.schema !== 'medcoel.labels.v1' ||
      !Array.isArray(labelTable.structures)) throw Error('REVIEW_INVALID_SPINE_LABEL_TABLE');
  const palette = new Map();
  for (const item of labelTable.structures) {
    if (!Number.isInteger(item.id) || item.id < 1 || item.id > 255 ||
        !Array.isArray(item.rgb) || item.rgb.length !== 3 ||
        item.rgb.some(v => !Number.isInteger(v) || v < 0 || v > 255)) {
      throw Error('REVIEW_INVALID_SPINE_LABEL_COLOR');
    }
    palette.set(item.id, item.rgb);
  }
  const [X, Y, Z] = mri.dims;
  const n = X * Y * Z;
  const bounds = [[X, -1], [Y, -1], [Z, -1]];
  const totalLabels = labels.data.subarray(352);
  for (let k = 0; k < n; k++) {
    const id = totalLabels[k];
    if (!id) continue;
    if (!palette.has(id)) throw Error('REVIEW_UNKNOWN_SPINE_LABEL:' + id);
    const x = k % X, y = Math.floor(k / X) % Y, z = Math.floor(k / (X * Y));
    for (const [axis, v] of [x, y, z].entries()) {
      bounds[axis][0] = Math.min(bounds[axis][0], v);
      bounds[axis][1] = Math.max(bounds[axis][1], v);
    }
  }
  if (bounds.some(v => v[1] < v[0])) throw Error('REVIEW_EMPTY_SPINE_MASK');
  const midpoint = bounds.map(([a, b]) => Math.floor((a + b) / 2));
  const specs = [
    { name: 'sagittal', width: Y, height: Z, slice: midpoint[0],
      coordinate: (u, v) => [midpoint[0], u, Z - 1 - v] },
    { name: 'coronal', width: X, height: Z, slice: midpoint[1],
      coordinate: (u, v) => [u, midpoint[1], Z - 1 - v] },
    { name: 'axial', width: X, height: Y, slice: midpoint[2],
      coordinate: (u, v) => [u, v, midpoint[2]] }
  ];
  const frames = [];
  for (const spec of specs) {
    const bare = Buffer.alloc(spec.width * spec.height * 4);
    const painted = Buffer.alloc(spec.width * spec.height * 4);
    let marked = 0;
    for (let v = 0; v < spec.height; v++) for (let u = 0; u < spec.width; u++) {
      const [x, y, z] = spec.coordinate(u, v);
      const voxelIndex = x + X * (y + Y * z);
      const intensity = mri.data.readInt16LE(352 + 2 * voxelIndex);
      const gray = Math.round(255 * Math.max(0, Math.min(1, (intensity - 134) / (1918 - 134))));
      const color = palette.get(totalLabels[voxelIndex]);
      const i = (v * spec.width + u) * 4;
      for (let c = 0; c < 3; c++) {
        bare[i + c] = gray;
        painted[i + c] = color ? Math.round(gray * 0.47 + color[c] * 0.53) : gray;
      }
      bare[i + 3] = 255; painted[i + 3] = 255;
      if (color) marked++;
    }
    frames.push({
      name: spec.name, width: spec.width, height: spec.height, index: spec.slice,
      markedPixels: marked,
      original: encodeRgbaPng(spec.width, spec.height, bare),
      overlay: encodeRgbaPng(spec.width, spec.height, painted)
    });
  }
  return frames;
}

const LEADS = ['I', 'II', 'III', 'aVR', 'aVL', 'aVF', 'V1', 'V2', 'V3', 'V4', 'V5', 'V6'];
const LAYOUT = [
  ['I', 'aVR', 'V1', 'V4'],
  ['II', 'aVL', 'V2', 'V5'],
  ['III', 'aVF', 'V3', 'V6']
];

/** Real PTB-XL ADU samples, 2.5 s per lead, 25 mm/s and 10 mm/mV. */
export function renderPrivateEcgSvg(wave) {
  if (!wave || wave.schema !== 'medcoel.ecg.v1' ||
      wave.fs !== 500 || wave.samples !== 5000 || wave.units !== 'mV' ||
      wave.paperSpeedMmPerS !== 25 || wave.gainMmPerMv !== 10 ||
      !Array.isArray(wave.leads) || wave.leads.length !== 12) {
    throw Error('REVIEW_ECG_UNEXPECTED_SCHEMA');
  }
  const byLead = new Map(wave.leads.map(l => [l.lead, l]));
  if (byLead.size !== LEADS.length ||
      LEADS.some(name => !byLead.has(name))) throw Error('REVIEW_ECG_LEADS_INCOMPLETE');
  const sampleCount = 1250, cellWidth = 268, cellHeight = 220, startX = 34, startY = 34;
  const w = startX + 4 * cellWidth + 20, h = startY + 3 * cellHeight + 25;
  const body = [];
  body.push('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + w + ' ' + h + '" role="img">');
  body.push('<title>Private PTB-XL ECG lead traces. First 2.5 seconds; clinical review pending.</title>');
  body.push('<rect width="' + w + '" height="' + h + '" fill="#fffafc"/>');
  for (let x = startX; x <= startX + 4 * cellWidth; x += 4)
    body.push('<path d="M' + x + ' ' + startY + 'V' + (startY + 3 * cellHeight) + '" stroke="' + ((x - startX) % 20 === 0 ? '#e5a7ac' : '#f8dce0') + '" stroke-width=".6"/>');
  for (let y = startY; y <= startY + 3 * cellHeight; y += 4)
    body.push('<path d="M' + startX + ' ' + y + 'H' + (startX + 4 * cellWidth) + '" stroke="' + ((y - startY) % 20 === 0 ? '#e5a7ac' : '#f8dce0') + '" stroke-width=".6"/>');
  for (let row = 0; row < 3; row++) for (let col = 0; col < 4; col++) {
    const name = LAYOUT[row][col], lead = byLead.get(name);
    if (!Number.isFinite(lead.gainAduPerMv) || lead.gainAduPerMv <= 0 ||
        !Number.isFinite(lead.baselineAdu) ||
        !Array.isArray(lead.adu) || lead.adu.length !== wave.samples ||
        lead.adu.some(x => !Number.isInteger(x) || x < -32768 || x > 32767)) {
      throw Error('REVIEW_ECG_BAD_ADU:' + name);
    }
    const originX = startX + col * cellWidth + 12, centreY = startY + row * cellHeight + cellHeight / 2;
    body.push('<text x="' + originX + '" y="' + (startY + row * cellHeight + 15) +
      '" fill="#12233e" font-family="sans-serif" font-size="15" font-weight="700">' + name + '</text>');
    const points = [];
    for (let i = 0; i < sampleCount; i++) {
      const mv = (lead.adu[i] - lead.baselineAdu) / lead.gainAduPerMv;
      const x = originX + i * (100 / wave.fs); // 25 mm/s, 4 px/mm.
      const y = centreY - mv * 40; // 10 mm/mV, 4 px/mm.
      points.push((i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1));
    }
    body.push('<path d="' + points.join(' ') + '" stroke="#14243e" fill="none" stroke-width="1.35" stroke-linejoin="round"/>');
  }
  body.push('<text x="' + startX + '" y="' + (h - 8) +
    '" fill="#31415b" font-family="sans-serif" font-size="13">2.5 detik pertama / lead · 25 mm/s · 10 mm/mV · label sumber BELUM divalidasi klinis</text>');
  body.push('</svg>');
  return body.join('\n');
}
